initJs:
function(container, apiUrl, tables) {
  // 現在のユーザーIDを取得（実際の実装では認証情報から取得）
  const currentUserId = localStorage.getItem('currentUserId') || 'user-001';

  // 中断記録データを取得する関数
  async function getBreakTime(workRecordId) {
    try {
      const breakRecords = await window.aivicApi.list(2); // 中断記録テーブル
      if (!breakRecords) return 0;

      const relatedBreaks = breakRecords.filter(br => br.作業記録ID === workRecordId);
      return relatedBreaks.reduce((total, br) => total + (br.中断時間 || 0), 0);
    } catch (error) {
      return 0;
    }
  }

  // 異常値警告を取得する関数
  async function getAnomalyWarning(workRecordId) {
    try {
      const anomalies = await window.aivicApi.list(4); // 異常値検出ログテーブル
      if (!anomalies) return '';

      const relatedAnomalies = anomalies.filter(a => 
        a.検出対象レコードID === workRecordId && a.確認状況 === '未確認'
      );

      if (relatedAnomalies.length > 0) {
        const highPriority = relatedAnomalies.find(a => a.重要度 === '高');
        return highPriority ? '⚠️' : '⚡';
      }
      return '';
    } catch (error) {
      return '';
    }
  }

  // 時間フォーマット関数
  function formatTime(timestamp) {
    if (!timestamp) return '-';
    const date = new Date(timestamp);
    return date.toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
  }

  // 日付フォーマット関数
  function formatDate(timestamp) {
    if (!timestamp) return '-';
    const date = new Date(timestamp);
    return date.toLocaleDateString('ja-JP');
  }

  // 作業時間フォーマット関数
  function formatDuration(minutes) {
    if (!minutes) return '-';
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return `${hours}h${mins.toString().padStart(2, '0')}m`;
  }

  // 承認状態のバッジスタイル
  function getApprovalBadge(status) {
    const styles = {
      '未承認': 'background: rgba(255, 193, 7, 0.15); color: #856404; padding: 2px 6px; border-radius: 4px; font-size: 11px;',
      '承認済み': 'background: rgba(40, 167, 69, 0.15); color: #155724; padding: 2px 6px; border-radius: 4px; font-size: 11px;',
      '差し戻し': 'background: rgba(220, 53, 69, 0.15); color: #721c24; padding: 2px 6px; border-radius: 4px; font-size: 11px;'
    };
    return `<span style="${styles[status] || styles['未承認']}">${status}</span>`;
  }

  // 進捗状況のバッジスタイル
  function getProgressBadge(status) {
    const styles = {
      '作業中': 'background: rgba(23, 162, 184, 0.15); color: #0c5460; padding: 2px 6px; border-radius: 4px; font-size: 11px;',
      '完了': 'background: rgba(40, 167, 69, 0.15); color: #155724; padding: 2px 6px; border-radius: 4px; font-size: 11px;',
      '中断': 'background: rgba(255, 193, 7, 0.15); color: #856404; padding: 2px 6px; border-radius: 4px; font-size: 11px;'
    };
    return `<span style="${styles[status] || styles['作業中']}">${status}</span>`;
  }

  // テーブル再描画関数
  async function renderRows(rows) {
    const tbody = container.querySelector('#records-tbody');
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="11" style="text-align: center; color: var(--text-muted);">記録がありません</td></tr>';
      return;
    }

    // 各行の中断時間と異常値警告を並行取得
    const rowsWithExtra = await Promise.all(rows.map(async (row) => {
      const [breakTime, warning] = await Promise.all([
        getBreakTime(row.作業記録ID),
        getAnomalyWarning(row.作業記録ID)
      ]);
      return { ...row, breakTime, warning };
    }));

    tbody.innerHTML = rowsWithExtra.map(row => `
      <tr data-id="${row.作業記録ID}">
        <td>${formatDate(row.作業日)}</td>
        <td>${row.プロジェクト名 || ''}</td>
        <td>${row.作業種別 || ''}</td>
        <td>${formatTime(row.作業開始時刻)}</td>
        <td>${formatTime(row.作業終了時刻)}</td>
        <td>${formatDuration(row.作業時間)}</td>
        <td>${formatDuration(row.breakTime)}</td>
        <td>${getProgressBadge(row.進捗状況)}</td>
        <td>${getApprovalBadge(row.承認状態)}</td>
        <td style="text-align: center;">${row.warning}</td>
        <td>
          <button class="action-btn secondary edit-btn" data-id="${row.作業記録ID}" style="margin-right: 4px;">修正</button>
          <button class="action-btn secondary delete-btn" data-id="${row.作業記録ID}">削除</button>
        </td>
      </tr>
    `).join('');
  }

  // 初期データ読み込み（現在のユーザーの記録のみ）
  window.aivicApi.list(1).then(allRecords => {
    if (allRecords) {
      const userRecords = allRecords.filter(record => record.作業員ID === currentUserId);
      renderRows(userRecords);
    } else {
      renderRows([]);
    }
  });

  // 検索ボタンのイベントリスナー
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const dateFrom = container.querySelector('#input-date-from').value;
    const dateTo = container.querySelector('#input-date-to').value;
    const projectFilter = container.querySelector('#input-project').value.toLowerCase();

    const allRecords = await window.aivicApi.list(1);
    if (!allRecords) return;

    let filteredRecords = allRecords.filter(record => record.作業員ID === currentUserId);

    // 日付フィルター
    if (dateFrom) {
      const fromDate = new Date(dateFrom);
      filteredRecords = filteredRecords.filter(record => {
        const recordDate = new Date(record.作業日);
        return recordDate >= fromDate;
      });
    }

    if (dateTo) {
      const toDate = new Date(dateTo);
      toDate.setHours(23, 59, 59, 999); // 終了日の23:59:59まで含める
      filteredRecords = filteredRecords.filter(record => {
        const recordDate = new Date(record.作業日);
        return recordDate <= toDate;
      });
    }

    // プロジェクトフィルター
    if (projectFilter) {
      filteredRecords = filteredRecords.filter(record => 
        (record.プロジェクト名 || '').toLowerCase().includes(projectFilter)
      );
    }

    renderRows(filteredRecords);
  });

  // CSVエクスポートボタン
  container.querySelector('#btn-export').addEventListener('click', async () => {
    const allRecords = await window.aivicApi.list(1);
    if (!allRecords) return;

    const userRecords = allRecords.filter(record => record.作業員ID === currentUserId);

    const headers = ['作業日', 'プロジェクト名', '作業種別', '開始時刻', '終了時刻', '作業時間(分)', '作業場所', '作業内容', '進捗状況', '承認状態', '備考'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...userRecords.map(record => [
        formatDate(record.作業日),
        `"${(record.プロジェクト名 || '').replace(/"/g, '""')}"`,
        `"${(record.作業種別 || '').replace(/"/g, '""')}"`,
        formatTime(record.作業開始時刻),
        formatTime(record.作業終了時刻),
        record.作業時間 || 0,
        `"${(record.作業場所 || '').replace(/"/g, '""')}"`,
        `"${(record.作業内容 || '').replace(/"/g, '""')}"`,
        record.進捗状況 || '',
        record.承認状態 || '',
        `"${(record.備考 || '').replace(/"/g, '""')}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `作業記録_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // メニューに戻るボタン
  container.querySelector('#btn-back').addEventListener('click', () => {
    window.showScreen('scr-1778907133295');
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener('click', async (e) => {
    // 削除ボタン
    const deleteBtn = e.target.closest('.delete-btn');
    if (deleteBtn) {
      if (!confirm('この作業記録を削除しますか？')) return;

      const recordId = deleteBtn.dataset.id;
      const result = await window.aivicApi.delete(1, recordId);
      if (result !== null) {
        // 削除成功後、リストを再読み込み
        const allRecords = await window.aivicApi.list(1);
        if (allRecords) {
          const userRecords = allRecords.filter(record => record.作業員ID === currentUserId);
          renderRows(userRecords);
        }
      }
      return;
    }

    // 修正ボタン
    const editBtn = e.target.closest('.edit-btn');
    if (editBtn) {
      const recordId = editBtn.dataset.id;
      // 修正画面に遷移（レコードIDをローカルストレージに保存）
      localStorage.setItem('editRecordId', recordId);
      window.showScreen('scr-1778907343735');
      return;
    }
  });

  // 今日の日付を初期値として設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#input-date-from').value = today;
  container.querySelector('#input-date-to').value = today;
}
